test("定義元の外からは成否の判別子を読めない", () => {
  const result = decoded(true);

  // @ts-expect-error 判別子のキーは定義元の外から名前を持てない（TS2339）
  const discriminant = result.ok;

  expect(discriminant).toBeUndefined();
});

test("定義元の外では値リテラルで結果を作れない", () => {
  // @ts-expect-error 判別子のキーは定義元の外から書けない（TS2353）
  const made: Result<number, string> = { ok: true, value: 42 };

  expect(made).not.toEqual(Result.ok(42));
});

test("成否の判別子のキーは定義元から持ち出せない", async () => {
  const module = await import("../Result");

  // @ts-expect-error 判別子のキーは export しない（TS2339）
  expect(module.OkTag).toBeUndefined();
});

test("成否の判別子は文字列のキーとして現れない", () => {
  expectTypeOf<Extract<keyof Ok<number>, string>>().toEqualTypeOf<"value">();
  expectTypeOf<Extract<keyof Err<string>, string>>().toEqualTypeOf<"error">();
});

test("定義元の外からは在／不在の判別子を読めない", () => {
  const option = Option.fromNullable<number>(42);

  // @ts-expect-error 判別子のキーは定義元の外から名前を持てない（TS2339）
  const discriminant = option.some;

  expect(discriminant).toBeUndefined();
});

test("定義元の外では値リテラルで不在を作れない", () => {
  // @ts-expect-error 判別子のキーは定義元の外から書けない（TS2353）
  const made: Option<number> = { some: false };

  expect(made).not.toEqual(Option.none);
});

test("在／不在の判別子のキーは定義元から持ち出せない", async () => {
  const module = await import("../Option");

  // @ts-expect-error 判別子のキーは export しない（TS2339）
  expect(module.SomeTag).toBeUndefined();
});

test("在／不在の判別子は文字列のキーとして現れない", () => {
  expectTypeOf<Extract<keyof Some<number>, string>>().toEqualTypeOf<"value">();
  expectTypeOf<Extract<keyof None, string>>().toEqualTypeOf<never>();
});

test("値が undefined の成功と失敗は、比べると別物になる", () => {
  // 値も中身も undefined だと判別子しか違わないので、比較が判別子を見なくなる
  // （キーを非列挙にする等）とここが等しくなる。
  expect(Result.ok(undefined)).not.toEqual(Result.err(undefined));
});

test("定義元が評価し直されても、それ以前に作った値を判定できる", async () => {
  const before = await import("../Result");
  const old = before.Result.ok(1);

  vi.resetModules();
  const after = await import("../Result");

  expect(after.Result).not.toBe(before.Result);
  expect(after.Result.isOk(old)).toBe(true);
});

test("定義元が評価し直されても、それ以前に作った値を判定できる", async () => {
  const before = await import("../Option");
  const old = before.Option.some(1);

  vi.resetModules();
  const after = await import("../Option");

  expect(after.Option).not.toBe(before.Option);
  expect(after.Option.isSome(old)).toBe(true);
});

